import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int num = scanner.nextInt();
        int den = scanner.nextInt();
        int max_iter = scanner.nextInt();
        double ratio = (double) num / den;
        double target = 1 + ratio;
        double min_difference = 1e9; // large initial value
        int best_num = 0;
        int best_den = 1;

        for (int i = 1; i <= max_iter; i++) {
            double candidate1 = (double) ((int) (ratio * i)) / i;
            double diff1 = Math.abs(candidate1 - ratio);
            if (diff1 < min_difference) {
                min_difference = diff1;
                best_num = (int) (ratio * i);
                best_den = i;
            }
            double candidate2 = (double) ((int) (ratio * i + 1)) / i;
            double diff2 = Math.abs(candidate2 - ratio);
            if (diff2 < min_difference) {
                min_difference = diff2;
                best_num = (int) (ratio * i) + 1;
                best_den = i;
            }
        }
        System.out.println(best_num + "/" + best_den);
        scanner.close();
    }
}
